    7:{...visuals[7],artwork:'supply-chain',caption:'The Binance case connects tooling, recruitment, internal AI, deployment and signing. Each handoff is a learning decision.',risk:'Authority crosses several trusted systems.',signal:'Linked endpoint, AI, deployment and signing events.',action:'Constrain and monitor each consequential authority.'},
    8:{...visuals[8],artwork:'identity',caption:'The DNB attempt shows why a convincing face or voice does not establish payment authority.',risk:'Executive impersonation changes a payment decision.',signal:'An unusual invitation, beneficiary change or approval bypass.',action:'Verify through an established independent contact route.'},
    11:{...visuals[11],artwork:'identity',caption:'The fictional applicant’s identity story needs independent evidence, not only a realistic image.',risk:'Synthetic identity material passes a surface check.',signal:'Conflicting identity, device and account behaviour.',action:'Use proportionate enhanced verification and review.'},
